import numpy as np
from scipy.optimize import least_squares
def run(basis_fn, nl0):
    best=None
    for s in range(12):
        rs=np.random.RandomState(s)
        p0=np.array(nl0)*(1+0.3*rs.randn(len(nl0)))
        def res(nl):
            X=basis_fn(nl)
            c,*_=np.linalg.lstsq(X,dA_dt,rcond=None)
            return X@c-dA_dt
        try:
            r=least_squares(res,p0)
            e=np.mean(r.fun**2)/np.var(dA_dt)
            if best is None or e<best[0]: best=(e,r.x)
        except Exception: pass
    return best
